"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0893-03-23:0":{"b": ["Emir samanidzki Ismâ'îl b. Ahmad zdobył Talas (Tarâz); Samanidzi osiągnęli na wschodzie największy zasięg", "a25f7598"], "d": ["Ismâ'îl b. Ahmad, aby chronić Mâwarâ’ an-nahr przed najazdami niemuzułmańskich Turków, zorganizował wyprawę sięgającą Tarâz (Talas) i zajął miasto; większość tureckich emirów i dihkanów tam żyjących przyjęła islam, a Oğulçak, który utracił Talas, wschodni ośrodek Karachanidów, przeniósł stolicę do Kaszgaru.", "8bf208a3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0902-08-01:0":{"b": ["Upadła Taormina: utracono ostatnią twierdzę Bizancjum na Sycylii", "525abc8c"], "d": ["Wraz ze zdobyciem Taorminy przez Arabów dobiegło końca panowanie Bizancjum na wyspie Sycylii; pozostały tylko ziemie w południowej Italii.", "9e2eb491"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0903-01-01:0":{"b": ["Karmaci zajęli Hamę, Hims, Ma'arrat an-Nu'mân i Baalbek; wysłane oddziały Tulunidów zostały pokonane (290/903).", "291ecf32"], "d": ["Karmaci zajęli Hamę, Hims, Ma'arrat an-Nu'mân i Baalbek; wysłane oddziały Tulunidów zostały pokonane (290/903).", "291ecf32"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0911-01-01:0":{"b": ["Armia Ujgurów z Kan-chou zajęła Tun-huang", "36ec7038"], "d": ["Tun-huang, ośrodek autonomicznego królestwa założonego w 905 przez chińskiego dowódcę, zostało w 911 zdobyte przez armię ujgurską pod dowództwem Tegina; zwycięstwo zwiększyło prestiż Ujgurów z Kan-chou u Chińczyków.", "3bffe840"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0914-01-01:0":{"b": ["Symeon zdobył Adrianopol", "fe0efa60"], "d": ["Car Bułgarów Symeon zajął w 914 Hadrianopolis (Adrianopol); miasto przez długi czas było sceną wojen bizantyjsko-bułgarskich.", "0d8b77bc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0923-11-19:0":{"b": ["Li Cunxu wkroczył do Kaifeng: Późniejsze Liang upadło", "aebaab18"], "d": ["Li Siyuan, awangarda Li Cunxu, który rozbił armię Liang w Zhongdu, o świcie stanął pod Bramą Fengqiu w Kaifeng; namiestnik Liang w Kaifeng Wang Zan poddał miasto, a Li Cunxu wkroczył do miasta przez Bramę Daliang.", "4ee60f2e"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0934-01-01:0":{"b": ["Bizancjum zdobyło Melitenę", "fd0898d0"], "d": ["Armia bizantyjska pod dowództwem domestika Wschodu Jana Kurkuasa dotarła do Eufratu i zdobyła w 934 Melitenę; w 943 zajęto także Majjafarikin, Amidę, Daras i Nisibis.", "46c833cc"]},
